    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Inits the METALMSupplierVolumetricRebateHeader fields with default values.
    /// </summary>
    public void initValue()
    {
        super();
        this.DocumentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        this.TransactionDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        this.Status = METALMSupplierVolumetricRebateStatus::Created;
        this.CurrencyCode = Ledger::accountingCurrency(CompanyInfo::find().RecId);

        this.setDimensions();
        
    }

/// <summary>
/// This method will set financial dimensions based on type. 
/// </summary>
public void setDimensions()
{
    VendParameters      vendParameters = VendParameters::find();
    if (this.Type == METALMSupplierVolumetricRebateType::SVR)
    {
        this.FinancialDimension = vendParameters.METSVRFinancialDimension;
    }
    else if(this.Type == METALMSupplierVolumetricRebateType::RDA)
    {
        this.FinancialDimension = vendParameters.METRDAFinancialDimension;
    }
}

    /// <summary>
    /// Validate customer account
    /// </summary>
    /// <param name = "_fieldIdToCheck">Field id</param>
    /// <returns>if validation was successful</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);
        
        if (ret)
        {
            switch (_fieldIdToCheck)
            {
                case fieldNum(METALMSupplierVolumetricRebateHeader, CustomerAccount) :
                    if (!this.custTable().RecId)
                    {
                        ret = checkFailed(strFmt("@MET:CustAccNumValidation", this.CustomerAccount, this.CustLegalEntity));
                    }
            }

        }

        return ret;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateWrite method for METALMSupplierVolumetricRebateHeader records
    /// </summary>
    /// <returns>true if record is valid for write, otherwise false</returns>
    public boolean validateWrite()
    {
        boolean ret;

        if (!this.Number)
        {
            this.Number = NumberSeq::newGetNum(
                VendParameters::METnumRefALMSupplierVolumetricRebateNumber()).num();
        }

        ret = super();

        ret = ret && this.validateStatus();
       
        return ret;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateDelete method for METALMSupplierVolumetricRebateHeader records
    /// </summary>
    /// <returns>true if record is valid for delete, otherwise false</returns>
    public boolean validateDelete()
    {
        boolean ret;

        ret = super();

