    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021  
    /// Checks on Status field of <t>METALMSupplierVolumetricRebateHeader</t> record
    /// </summary>
    /// <returns>true if Status is different than Processed, otherwise false</returns>
    public boolean validateStatus()
    {
        if (this.Status == METALMSupplierVolumetricRebateStatus::Processed)
        {
            return checkFailed("@MET:ALMSVRCannotBeModified");
        }

        return true;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// FindRecId method for <t>METALMSupplierVolumetricRebateHeader</t>
    /// </summary>
    /// <param name = "_recId">RecId</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns><t>METALMSupplierVolumetricRebateHeader</t> record if found,
    /// otherwise null</returns>
    static METALMSupplierVolumetricRebateHeader findRecId(
        RecId _recId,
        boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateHeader header;

        if (_recId)
        {
            header.selectForUpdate(_forupdate);

            select firstonly header
                where header.RecId == _recId;
        }

        return header;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Find method for <t>METALMSupplierVolumetricRebateHeader</t>
    /// </summary>
    /// <param name = "_number">METALMSupplierVolumetricRebateHeader Number</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns><t>METALMSupplierVolumetricRebateHeader</t> record if found,
    /// otherwise null</returns>
    static METALMSupplierVolumetricRebateHeader find(
        METALMSupplierVolumetricRebateNumber _number,
        boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateHeader header;

        if (_number != '')
        {
            header.selectForUpdate(_forupdate);

            select firstonly header
                where header.Number == _number;
        }

        return header;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Exist method for <t>METALMSupplierVolumetricRebateHeader</t>
    /// </summary>
    /// <param name = "_number">METALMSupplierVolumetricRebateHeader Number</param>
    /// <returns>true if record exists, otherwise false</returns>
    static boolean exist(METALMSupplierVolumetricRebateNumber _number)
    {
        boolean found;

        found = (select firstonly RecId from 
                    METALMSupplierVolumetricRebateHeader
                    where
                    METALMSupplierVolumetricRebateHeader.Number == _number)
            .RecId != 0;
         
        return found;
    }

