/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// CustTable associated with CustomerAccount field
/// </summary>
/// <returns>CustTable record if found, null otherwise</returns>
public CustTable custTable()
{
    CustTable   custTable;
    if(this.CustLegalEntity)
    {
        changecompany(this.CustLegalEntity)
        {
            custTable   = CustTable::find(this.CustomerAccount);
        }
    }
    return custTable;
}

