    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// ModifiedField method for METALMSupplierVolumetricRebateLine records
    /// </summary>
    /// <param name = "_fieldId">The field ID for the modified field.</param>
    public void modifiedField(FieldId _fieldId)
    {
        METALMSupplierVolumetricRebateLine line;

        super(_fieldId);

        switch (_fieldId)
        {
            Case fieldNum(METALMSupplierVolumetricRebateHeader, Type):
                this.setDimensions();
                // modify lines accordingly     
                while select forupdate line
                    where   line.ALMSupplierVolumetricRebateNumber == this.Number
                {
                    ttsbegin;
                    line.setDimensions();
                    line.doUpdate();
                    ttscommit;
                }
                break;

            Case fieldNum(METALMSupplierVolumetricRebateHeader, FinancialDimension):
                // modify lines accordingly
                while select forupdate line
                    where   line.ALMSupplierVolumetricRebateNumber == this.Number
                {
                    ttsbegin;
                    line.FinancialDimension = this.FinancialDimension;
                    line.doUpdate();
                    ttscommit;
                }
                break;

            Case fieldNum(METALMSupplierVolumetricRebateHeader, CustomerAccount):
                this.CustDueDate = this.calcCustDueDate();
                break;

            Case fieldNum(METALMSupplierVolumetricRebateHeader, VendorAccount):
                this.VendDueDate = this.calcVendDueDate();
                break;
        }
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 20Jul2021
    /// Static method to check wether there are Cust lines for a ALM Supplier Volumetric
    /// rebate or not
    /// </summary> 
    /// <param name = "_number">ALM Supplier Volumetric Rebate Number</param>
    /// <returns>true if there is at least one Cust ALM Supplier Volumetric Rebate Line
    /// for the header</returns>
    static boolean hasCustLines(METALMSupplierVolumetricRebateNumber _number)
    {
        METALMSupplierVolumetricRebateLine line;

        select firstonly RecId from line
            where line.ALMSupplierVolumetricRebateNumber == _number
            && line.CustVend == CustVendACType::Cust;

        if(line.RecId != 0)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 20Jul2021
    /// Static method to check wether there are Vend lines for a ALM Supplier Volumetric
    /// rebate or not
    /// </summary>
    /// <param name = "_number">ALM Supplier Volumetric Rebate Number</param>
    /// <returns>true if there is at least one Vend ALM Supplier Volumetric Rebate Line
    /// for the header</returns>
    static boolean hasVendLines(METALMSupplierVolumetricRebateNumber _number)
    {
        METALMSupplierVolumetricRebateLine line;

        select firstonly RecId from line
            where line.ALMSupplierVolumetricRebateNumber == _number
            && line.CustVend == CustVendACType::Vend;

        if(line.RecId != 0)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// Calculate the due date for Customer.
    /// </summary>
    /// <returns>Due date.</returns>
    public DueDate calcCustDueDate()
    {
        DueDate         dueDate;
        CustTable       custTable;
        PaymTerm        paymterm;

        if(this.CustLegalEntity)
        {
            changecompany(this.CustLegalEntity)
            {
                custTable   = this.custTable();
                paymterm    = PaymTerm::find(custTable.PaymTermId);
                dueDate     = paymterm.due(this.TransactionDate, custTable.PaymDayId);
            }
        }
        return dueDate;
    }

    /// <summary>
    /// Calculates the due date for Vendor
    /// </summary>
    /// <returns>Due date</returns>
    public DueDate calcVendDueDate()
    {
        DueDate         dueDate;
        VendTable       vendTable = VendTable::find(this.VendorAccount);
        PaymTerm        paymterm = PaymTerm::find(vendTable.PaymTermId);

        dueDate = paymterm.due(this.TransactionDate, vendTable.PaymDayId);

        return dueDate;
    }

    /// <summary>
    ///    Updates an existing record in the <c>METALMSupplierVolumetricRebateHeader</c> table.
    /// </summary>
    public void update()
    {
        this.updateDueDates();

        super();
    }

    /// <summary>
    ///    Insrets record in the <c>METALMSupplierVolumetricRebateHeader</c> table.
    /// </summary>
    public void insert()
    {
        this.updateDueDates();

        super();
    }

    /// <summary>
    /// This method updates customer and vendor due dates.
    /// </summary>
    public void updateDueDates()
    {
        if (this.CustDueDate == dateNull())
        {
            this.CustDueDate = this.calcCustDueDate();
        }

        if (this.VendDueDate == dateNull())
        {
            this.VendDueDate = this.calcVendDueDate();
        }
    }

/// <summary>
/// Calculates sums of amount of customer lines.
/// </summary>
/// <returns>Amount</returns>
public Amount totalCustAmount()
{
    return (select sum(Amount)  from METALMSupplierVolumetricRebateLine
        where METALMSupplierVolumetricRebateLine.ALMSupplierVolumetricRebateNumber == this.Number
        && METALMSupplierVolumetricRebateLine.CustVend == CustVendACType::Cust).Amount;
}

/// <summary>
/// Calculates sums of amount of vendor lines.
/// </summary>
/// <returns>Amount</returns>
public Amount totalVendAmount()
{
    return (select sum(Amount)  from METALMSupplierVolumetricRebateLine
        where METALMSupplierVolumetricRebateLine.ALMSupplierVolumetricRebateNumber == this.Number
        && METALMSupplierVolumetricRebateLine.CustVend == CustVendACType::Vend).Amount;
}

    /// <summary>
    /// Retrieves the total invoice amount for the required action on the <c>CustInvoiceTable</c> record.
    /// </summary>
    /// <returns>
    /// A string that contains the total invoice amount for the required action.
    /// </returns>
    display InvoiceAmountMST displayInvoiceAmount()
    {
        InvoiceAmountMST    invoiceAmountMST = 0;
        CustInvoiceTable    custInvoiceTable;

        changecompany(this.CustLegalEntity)
        {
            while select firstonly custInvoiceTable
                where   custInvoiceTable.PurchOrderFormNum  == this.Number
            {
                invoiceAmountMST = custInvoiceTable.displayInvoiceAmount();
            }
        }
        return invoiceAmountMST;
    }

    /// <summary>
    /// Retrieves the date the Customer Transaction was closed
    /// </summary>
    /// <returns>Date the Customer Transaction was closed </returns>
    display METClosedDate displayClosedDate()
    {
        METClosedDate   closedDate;
        CustInvoiceJour custInvoiceJour;
        CustInvoiceTable custInvoiceTable;
        CustTrans       custTrans;

        changecompany(this.CustLegalEntity)
        {
            while select firstonly custInvoiceTable
                where   custInvoiceTable.PurchOrderFormNum  == this.Number

                join    RecId from custInvoiceJour
                where   custInvoiceJour.InvoiceId           == custInvoiceTable.InvoiceId 
                &&      custInvoiceJour.InvoiceDate         == custInvoiceTable.InvoiceDate 
                &&      custInvoiceJour.NumberSequenceGroup == custInvoiceTable.NumberSequenceGroup
                &&      custInvoiceJour.SalesId             == "" //no sales id on FTI

                join    Closed from custTrans
                where   custTrans.Invoice           == custInvoiceJour.InvoiceId
                &&      custTrans.AccountNum        == custInvoiceJour.InvoiceAccount
                &&      custTrans.TransDate         == custInvoiceJour.InvoiceDate
                &&      custTrans.Voucher           == custInvoiceJour.LedgerVoucher
                &&      custTrans.Closed
            {
                closedDate = custTrans.Closed;
            }
        }
    
        return closedDate;
    }

    /// <summary>
    /// MPJ_19298 FTI VOLRB
    /// Find method for <t>METALMSupplierVolumetricRebateHeader</t>
    /// </summary>
    /// <param name = "_number">METALMSupplierVolumetricRebateHeader Number</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns><t>METALMSupplierVolumetricRebateHeader</t> record if found, otherwise null</returns>
    static METALMSupplierVolumetricRebateHeader findByNumberCustLegalEntity(METALMSupplierVolumetricRebateNumber    _number,
                                                                            LegalEntityDataAreaId                   _custLegalEntity,
                                                                            boolean                                 _forupdate = false)
    {
        METALMSupplierVolumetricRebateHeader header;

        if (_number && _custLegalEntity)
        {
            header.selectForUpdate(_forupdate);

            select firstonly crosscompany header
                where   header.Number == _number
                &&      header.CustLegalEntity == _custLegalEntity;
        }

        return header;
    }
